-- Stage 2: assess. One boolean per rule, so a quarantined
-- row records exactly why it was rejected.
assessed as (
    select
        *,
        (product_id is not null) as _dq_product_id_present,
        (base_price_zar >= 0) as _dq_base_price_zar_non_negative,
        (base_cost_zar >= 0) as _dq_base_cost_zar_non_negative,
        (coalesce(_dq_product_id_present, false) and coalesce(_dq_base_price_zar_non_negative, false) and coalesce(_dq_base_cost_zar_non_negative, false)) as _dq_is_valid,
        concat_ws(',',
            case when not coalesce(_dq_product_id_present, false) then 'product_id_present' end,
            case when not coalesce(_dq_base_price_zar_non_negative, false) then 'base_price_zar_non_negative' end,
            case when not coalesce(_dq_base_cost_zar_non_negative, false) then 'base_cost_zar_non_negative' end
